import{_ as o,c as a,o as t,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"后端开发规范","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/development-guide.md","filePath":"docs/backend/development-guide.md"}'),l={name:"docs/backend/development-guide.md"};function i(c,e,r,n,s,p){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="后端开发规范" tabindex="-1">后端开发规范 <a class="header-anchor vp-link" href="#后端开发规范" aria-label="Permalink to &quot;后端开发规范&quot;">​</a></h1><p>本文是仓库 <code>sdd/后端代码规范.md</code> 的<strong>文档站摘要</strong>，开发时以源码与 SDD 全文为准。</p><h2 id="分层与包结构" tabindex="-1">分层与包结构 <a class="header-anchor vp-link" href="#分层与包结构" aria-label="Permalink to &quot;分层与包结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>controller → service → mapper → domain</span></span>
<span class="line"><span>         ↘ dto (Bo 入参 / Vo 出参)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>Controller</strong>：只做参数校验、权限注解、调用 Service；补齐 <code>@Tag</code>、<code>@Operation</code>。</li><li><strong>Service</strong>：业务逻辑、事务边界。</li><li><strong>Mapper</strong>：MyBatis-Plus，XML 放在 <code>mapper/**/*.xml</code>。</li><li><strong>Bo</strong>：<code>@Validated(AddGroup.class)</code> / <code>UpdateGroup</code> 分组校验。</li><li><strong>Vo</strong>：返回给前端，敏感字段配合 <code>@Sensitive</code> 脱敏。</li></ul><h2 id="接口约定" tabindex="-1">接口约定 <a class="header-anchor vp-link" href="#接口约定" aria-label="Permalink to &quot;接口约定&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>修改/删除优先 <code>@PostMapping</code>，路径表达语义（如 <code>/remove</code>、<code>/update</code>）</td></tr><tr><td>响应</td><td>统一 <code>R&lt;T&gt;</code>，HTTP 常为 200，以 <code>code</code> 判断成败</td></tr><tr><td>分页</td><td><code>PageRequest</code> + <code>PageInfo</code></td></tr><tr><td>异常</td><td>使用 <code>WarningException</code> / <code>ErrorException</code>，<strong>禁止</strong>用 <code>IllegalArgumentException</code> 表示业务失败</td></tr><tr><td>对象转换</td><td><code>BeanUtil.copyProperties()</code></td></tr></tbody></table></div><h2 id="持久化" tabindex="-1">持久化 <a class="header-anchor vp-link" href="#持久化" aria-label="Permalink to &quot;持久化&quot;">​</a></h2><ul><li>主键：雪花 <code>assign_id</code>（<code>mybatis-plus.global-config</code>）。</li><li>逻辑删除字段：<code>del_flag</code>（1 删除 / 0 正常）。</li><li>库表变更：<strong>仅通过 Flyway</strong> <code>db/migration/V*.sql</code>，禁止手工改库不同步脚本。</li></ul><h2 id="配置与安全" tabindex="-1">配置与安全 <a class="header-anchor vp-link" href="#配置与安全" aria-label="Permalink to &quot;配置与安全&quot;">​</a></h2><ul><li>敏感配置：Jasypt <code>ENC(...)</code>，启动参数 <code>-Djasypt.encryptor.password=...</code>。</li><li>认证：Sa-Token，Header <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>调用方鉴权：OAuth Client <strong>HMAC</strong>（见 <a href="./modules/oauth2.html" class="vp-link">OAuth2 集成</a>）。</li><li>横切能力：优先复用 <code>quickboot-common</code>（Excel、防火墙、操作日志等），避免在 web 重复实现。</li></ul><h2 id="代码生成" tabindex="-1">代码生成 <a class="header-anchor vp-link" href="#代码生成" aria-label="Permalink to &quot;代码生成&quot;">​</a></h2><p>新增标准 CRUD 模块可先用 <a href="./modules/codegen.html" class="vp-link">代码生成</a> 产出骨架，再按规范手工调整 Bo/Vo 与权限标识。</p><h2 id="验证清单" tabindex="-1">验证清单 <a class="header-anchor vp-link" href="#验证清单" aria-label="Permalink to &quot;验证清单&quot;">​</a></h2><ul><li>[ ] 新接口已在 Swagger 可见且 Bo 校验完整</li><li>[ ] Flyway 脚本可重复执行、与实体字段一致</li><li>[ ] 未将 <code>client_secret</code> 等敏感信息写入日志</li><li>[ ] <code>mvn -pl quickboot-web -am test</code> 或至少 <code>mvn -pl quickboot-web package</code> 通过</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor vp-link" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./structure.html" class="vp-link">项目结构</a></li><li><a href="./../backend/api/index.html" class="vp-link">接口规范</a></li><li>仓库 <code>sdd/后端代码规范.md</code>、<code>openspec/project.md</code></li></ul>`,17)])])}const m=o(l,[["render",i]]);export{u as __pageData,m as default};
